const LING = new Set(['sabrathan@gmail.com','farahputri@gmail.com','dmluciahorea@gmail.com','roxanamoldovan25@gmail.com','mteres@terestraducciones.com','arandatrad@gmail.com','sara.guinot.trad@gmail.com','daniel@dgmultilingualservices.com','qrcodelocalization@gmail.com','root-translations@outlook.com','austra.muizniece@gmail.com','harald.roald@gmail.com','47natcha@gmail.com','ellen.de.venter@outlook.com','ilaria.roncaglia@gmail.com','silke.luehrmann@gmx.de','boh.vozniuk@gmail.com','vidiasc@gmail.com','ivanaturcin@ymail.com','julius.valkiunas@gmail.com','jaromirvicari@me.com','karahansisman@gmail.com','katri.varvikko@gmail.com','kenneth@phraseit.dk','translation@cornell.hu','ruckova.lucia@gmail.com','marit.teichmann@gmail.com','michal.tosza@translators.org.pl','mteixeira@sacradomus.com','bruno@bsttranslations.com','nerissaneptuno@gmail.com','straus.translations@gmail.com','quentinnguyen.localize@gmail.com','therese.svardsten@gmail.com','mjlocalize@gmail.com','silis.martins@gmail.com']);
const TARGET = ['es','hr','cs','da','nl','et','fil','fi','fr','de','el','hu','id','it','ko','lv','lt','ms','no','pl','pt','ro','sk','sl','sv','th','tr','uk','vi'];
const norm = s => String(s == null ? '' : s).replace(/\u00a0/g, ' ').replace(/\s+/g, ' ').trim();
const langMap = {}; const terms = []; const errors = []; const gmeta = []; const keyBodies = [];
for (const it of $input.all()) {
  const j = it.json; const b = j.body || {};
  if (Array.isArray(b.languages)) { for (const l of b.languages) langMap[l.lang_id] = l.lang_iso; continue; }
  if (Array.isArray(b.data)) { for (const t of b.data) terms.push(t); gmeta.push(b.meta || null); continue; }
  if (Array.isArray(b.keys)) { keyBodies.push(b); continue; }
  errors.push({ status: j.statusCode, body: JSON.stringify(b).slice(0, 300) });
}
const byEn = new Map(); const missingCount = {}; let emptyCells = 0;
for (const t of terms) {
  if (t.translatable === false || t.forbidden === true) continue;
  const tr = {};
  for (const x of (t.translations || [])) { const iso = langMap[x.langId]; if (iso && norm(x.translation)) tr[iso] = norm(x.translation); }
  const missing = TARGET.filter(i => !tr[i]);
  for (const i of missing) missingCount[i] = (missingCount[i] || 0) + 1;
  emptyCells += missing.length;
  if (!missing.length) continue;
  const entry = { id: t.id, term: t.term, missing };
  const ks = new Set([norm(t.term).toLowerCase()]); if (tr.en) ks.add(tr.en.toLowerCase());
  for (const k of ks) { if (!byEn.has(k)) byEn.set(k, []); byEn.get(k).push(entry); }
}
const agg = new Map(); let keysSeen = 0; let matchedKeys = 0;
for (const b of keyBodies) {
  for (const k of b.keys) {
    keysSeen++;
    if (k.is_plural) continue;
    const trs = k.translations || [];
    const en = trs.find(t => t.language_iso === 'en'); if (!en) continue;
    const enTxt = norm(en.translation); const lc = enTxt.toLowerCase();
    const entries = byEn.get(lc); if (!entries) continue;
    matchedKeys++;
    for (const e of entries) for (const iso of e.missing) {
      const t = trs.find(x => x.language_iso === iso); if (!t) continue;
      const txt = norm(t.translation); if (!txt) continue;
      const id = e.id + '|' + iso;
      if (!agg.has(id)) agg.set(id, { termId: e.id, term: e.term, iso, trusted: {}, other: {} });
      const a = agg.get(id);
      const by = t.modified_by_email || '';
      const trusted = !t.is_unverified && (t.is_reviewed || LING.has(by));
      const bucket = trusted ? a.trusted : a.other;
      if (!bucket[txt]) bucket[txt] = [];
      if (bucket[txt].length < 4) bucket[txt].push({ p: b.project_id.slice(0, 8), k: ((k.key_name || {}).web || '').slice(0, 80), en: enTxt, by: by.split('@')[0], rv: !!t.is_reviewed });
      else bucket[txt].push(1);
    }
  }
}
const out = [];
for (const a of agg.values()) out.push({ termId: a.termId, term: a.term, iso: a.iso, trusted: Object.fromEntries(Object.entries(a.trusted).map(([t, v]) => [t, { n: v.length, s: v.filter(x => typeof x === 'object') }])), other: Object.fromEntries(Object.entries(a.other).map(([t, v]) => [t, v.length])) });
return [{ json: { termsN: terms.length, gmeta: gmeta.map(m => JSON.stringify(m).slice(0, 200)), langs: Object.keys(langMap).length, emptyCells, missingCount, keysSeen, matchedKeys, projects: keyBodies.length, errors, results: out } }];
